insert into public.knowledge_sources (source_key, title, source_url, authority, jurisdiction, domain, source_type, priority, tags, cache_days, is_active) values ('tw-tfda-cosmetics-management-framework', 'TFDA Cosmetics Management Framework', 'https://www.fda.gov.tw/eng/siteContent.aspx?sid=10347', 'Taiwan Food and Drug Administration', 'TW', 'cosmetics', 'guidance', 'high', '["cosmetics","post-market-surveillance","adverse-event-reporting","pif","gmp"]'::jsonb, 30, true) on conflict (source_key) do update set title = excluded.title, source_url = excluded.source_url, authority = excluded.authority, jurisdiction = excluded.jurisdiction, domain = excluded.domain, source_type = excluded.source_type, priority = excluded.priority, tags = excluded.tags, cache_days = excluded.cache_days, is_active = true;
insert into public.knowledge_snapshots (source_key, content_hash, fetched_at, from_cache, bytes, text_chars, document_path, extract, metadata) values ('tw-tfda-cosmetics-management-framework', 'b42a98b5504998fe687fa9bc97a75111cb0264f3cf237d1f4e5c7c5657626236', '2026-06-26T01:28:18.296Z', true, 41542, 2780, 'data/knowledge/documents/tw-tfda-cosmetics-management-framework.md', 'Cosmetics Management Framework - Scope & Definition - Cosmetics - Food and Drug Administration, Department of Health Go To Content ::: Home Sitemap Contact us Bilingual Glossary 中文版 Go Hot： food additives, Nutrition label, Medicinal Products Food Drugs Controlled Drugs Medical Devices Cosmetics About Taiwan FDA ::: Cosmetics Scope & Definition Law & Regulations Inspection Science & Research ::: you are in： Home Cosmetics Scope & Definition Cosmetics Management Framework Cosmetics Cosmetics Management Framework 【Update Date： 2023-04-10 】 unit：醫療器材及化粧品組 The current cosmetics management system includes three parts: production source control, pre-market management and post-market surveillance. The production source control includes ensuring that manufacturers comply with the Establishment Standards for Cosmetics Manufactory and promotion of Cosmetics Good Manufacturing Practice Regulations (GMP); the pre-marketing management includes notification of cosmetic products and establishment of product information file to replace the registration of specific purpose cosmetics; post-market surveillance focuses on the quality monitoring plan and inspections of the cosmetic products across counties and cities, the establishment of product adverse event reporting system for cosmetics, regular monitor of the safety alert for domestic and global cosmetics and strengthening consumer awareness of safe cosmetics use to create a comprehensive cosmetics quality and safety protection network. News About FDA 1 Director General 2 Chronicle of History 3 Mission and Future Perspectives 4 Organization and Functions 5 Contact 6 FDA Logo Product 1 Food 2 Drugs 3 Controlled Drugs 4 Medical Devices 5 Cosmetics 6 Inspection & Research 7 Science and Research 8 GXP Inspection & Lab Accreditation 9 Inspection Law & Regulations 1 Food 2 Drugs 3 Controlled Drugs 4 Medical Devices 5 Cosmetics 6 Inspections 7 Compliance & Accreditation 8 Others Inspection & Research 1 Science and Research 2 GXP Inspection & Lab Accreditation 3 Inspection Journal of Food and Drug Analysis (JFDA) 1 About the JFDA 2 Call for Paper Flyer 3 The Most Cited Articles in 2024 4 Instructions to Authors 5 Impact Factor 6 Editorial Board 7 Articles & Issues 8 Home page 9 Submit Article Conference & Workshop Bilingual Glossary ::: Security Policy Privacy Policy ADD : No.109, Ln. 130, Sec. 1, Academia Rd., Nangang Dist., Taipei City 115, Taiwan (R.O.C.) MAP TEL : 886-2-2787-8000 Consultation Service Hotline Tel: (02) 2787-8200 (Service hours: Weekdays 8:00 AM – 6:00 PM) National 1919 Food Safety Hotline Tel: 1919 (charges apply – local calls at regular rate; mobile phone NT$3.6/min or NT$0.06/sec) Copyright 2018,Taiwan FDA. All Rights Reserved. Best viewed with 1024x768 pixel or above is recommended.', '{"source_registry_version":"2026-06-26","source_ops_metadata_version":"2026-06-26","authority":"Taiwan Food and Drug Administration","domain":"cosmetics","tags":["cosmetics","post-market-surveillance","adverse-event-reporting","pif","gmp"],"source_ops":{"id":"tw-tfda-cosmetics-management-framework","languages":["en"],"review_owner":"tw-cosmetics-labeling-pif","selector_strategy":"official-html-main-content","date_strategy":"page-update-or-publication-date","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"official-page-text-cache"},"languages":["en"],"review_owner":"tw-cosmetics-labeling-pif","selector_strategy":"official-html-main-content","date_strategy":"page-update-or-publication-date","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"official-page-text-cache","format":"html","page_coun