insert into public.knowledge_snapshots (source_key, content_hash, fetched_at, from_cache, bytes, text_chars, document_path, extract, metadata) values ('tw-moj-food-contact-sanitation-standards', 'bebe9f12d2367f114a5611ddf5948a99c713454e8afa7a2c80dba2ff81475a79', '2026-06-26T03:00:44.102Z', true, 26084, 2868, 'data/knowledge/documents/tw-moj-food-contact-sanitation-standards.md', 'Sanitation Standards for Food Utensils, Containers and Packages - Article Content - Laws & Regulations Database of The Republic of China (Taiwan) Goto Main Content ::: Sitemap 中文 Search Search News Law Convention News Law Convention Searching Justices of the Constitutional Court Related Websites Sitemap 中文 ::: Location： Home Law Article Content P Print Select Folders： Save Save Add New Folder Manage Folders Article Content Title： Sanitation Standards for Food Utensils, Containers and Packages CH Amended Date： 2023-01-11 Category： Ministry of Health and Welfare（衛生福利部） Attachment： Annex table 1 General requirements.PDF Annex table 2 Requirements for plastic materials.PDF Annex table 3 Annex table 3 Materials requirements for dairy products.PDF Article Content Article Search Content Search Legislative History Article 1 The Standards are prescribed in accordance with the provisions of Article 17 of the Act Governing Food Safety and Sanitation. Article 2 Plastic food containers and packages shall not be recycled to repackage food then sell. Article 3 Food utensils, containers and packages shall not have discoloration, off odor and flavor, contamination, moulds, foreign matter or stripped fiber. Article 4 The food utensils and containers used for children under three years old, shall not add di-(2-ethylhexyl) phthalate (DEHP), Di-n-octyl phthalate (DNOP), dibutyl phthalate (DBP) and Benzyl butyl phthalate (BBP). Article 5 Plastic infant feeding bottles shall not contain of Bisphenol A. Article 6 Food utensils, containers and packages shall meet the requirements according to the following standard tests： 1. General requirements as Annex table 1. 2. The plastic materials listed in the Annex table 2, shall also comply with the Annex table 1. 3. The containers and packages for dairy products shall comply with the Annex table 3. Annex table 1 General requirements.PDF Annex table 2 Requirements for plastic materials.PDF Annex table 3 Annex table 3 Materials requirements for dairy products.PDF Article 7 The Standards shall be implemented on the date of promulgation. ::: News Law Convention Searching Justices of the Constitutional Court Related Websites E-PAPER VISITORS 43,472,880 MONTHLY VISITORS 399,035 ONLINE VISITORS 1 E-PAPER SUBSCRIBERS 20,729 This website does not provide legal counseling service, please contact with related public offices for more information. In case of any discrepancy between the English version and the Chinese version, the latter shall prevail. The last update date of laws and regulations data：2026/06/18 │ Open Data Statement │ Declaration on Privacy Right Protection │ Information Security Policy │ EMail │ OPERATING BY THE WORKING GROUP OF THE R.O.C LAWS & REGULATIONS DATABASE, MINISTRY OF JUSTICE. NO. 130, Sec. 1, Chongqing S. Rd., Taipei, 100204, Taiwan(R.O.C.) Service Phone-Call: +886-2-2191-0189 Top', '{"source_registry_version":"2026-06-26","source_ops_metadata_version":"2026-06-26","authority":"Ministry of Health and Welfare / MOJ Laws and Regulations Database","domain":"food_contact_materials","tags":["food-contact-materials","food-utensils","food-containers","packaging","sanitation-standard","plastic","recycled-plastic","bpa","bisphenol-a","phthalates","dehp","dnop","dbp","bbp","infant-feeding-bottles","standard-tests"],"source_ops":{"id":"tw-moj-food-contact-sanitation-standards","languages":["en"],"review_owner":"tw-food-contact-materials","selector_strategy":"law-database-article-extract","date_strategy":"moj-law-amended-date","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"official-page-text-cache"},"languages":["en"],"review_owner":"tw-food-contact-materials","selector_strategy":"law-database-article-extract","date_strategy":"moj-law-amended-date","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"official-page-text-cache","format":"html","page_count":null,"parse_error":null,"fetched_url":"https://law.moj.gov.tw/ENG/LawClass/LawAll.aspx?pcode=L0040019","extra_fetched_urls":[],"cache_days":30,"cache_expires_at":"2026-07-26T03:00:44.102Z","cache_status":"fresh","browser_capture_path":null,"screenshot_path":null}'::jsonb) on conflict (source_key, content_hash) do update set fetched_at = excluded.fetched_at, from_cache = excluded.from_cache, bytes = excluded.bytes, text_chars = excluded.text_chars, document_path = excluded.document_path, extract = excluded.extract, metadata = excluded.metadata;
insert into public.knowledge_sources (source_key, title, source_url, authority, jurisdiction, domain, source_type, priority, tags, cache_days, is_active) values ('tw-tfda-food-container-smart-use-2026', 'Check, Read and Properly Use: Three Tips for Smart Using Food Containers', 'https://www.fda.gov.tw/eng/newsContent.aspx?id=31513', 'Taiwan Food and Drug Administration', 'TW', 'food_contact_materials', 'consumer_notice', 'medium', '["food-contact-materials","food-containers","material","heat-resistance","microwave-safe","single-use","consumer-safety"]'::jsonb, 14, true) on conflict (source_key) do update set title = excluded.title, source_url = excluded.source_url, authority = excluded.authority, jurisdiction = excluded.jurisdiction, domain = excluded.domain, source_type = excluded.source_type, priority = excluded.priority, tags = excluded.tags, cache_days = excluded.cache_days, is_active = true;
insert into public.knowledge_snapshots (source_key, content_hash, fetched_at, from_cache, bytes, text_chars, document_path, extract, metadata) values ('tw-tfda-food-container-smart-use-2026', 'bf27dc3ac0006d3e98cdb86725a6dcfbef26d345b89f41ef4447d738e9f15e3e', '2026-07-10T05:40:08.743Z', false, 45197, 2758, 'data/knowledge/documents/tw-tfda-food-container-smart-use-2026.md', 'Food and Drug Administration, Department of Health Go To Content ::: Home Sitemap Contact us Bilingual Glossary 中文版 Go Hot： food additives, Nutrition label, Medicinal Products Food Drugs Controlled Drugs Medical Devices Cosmetics About Taiwan FDA ::: you are in： Home News &amp; Events News & Events Check, Read and Properly Use: Three Tips for Smart Using Food Containers 【Update Date： 2026-05-05 】 unit：區管理中心 With the popularization of takeout and dining out, the safety of food containers has become more important than ever. The Taiwan Food and Drug Administration (TFDA) reminds the public to follow three simple steps— "Check, Read, and Use Properly" —to ensure food safety. 1. Check the Material Choose materials that are suitable for their intended use. Pay attention to the heat resistance of plastic products, select stainless steel from the 300 series (e.g., 304 or 316), and choose clear or undecorated glass and ceramic products whenever possible. 2. Read the Label Check key product information, including the material type, heat resistance, and usage instructions (e.g., whether the product is microwave-safe). 3. Use Properly Replace damaged containers, avoid using non-heat-resistant products for hot foods, and do not reuse single-use tableware. The TFDA reminds consumers that following these steps can effectively reduce risks and help ensure food safety. For more detailed information, please visit the official TFDA website at https://www.fda.gov.tw. News About FDA 1 Director General 2 Chronicle of History 3 Mission and Future Perspectives 4 Organization and Functions 5 Contact 6 FDA Logo Product 