insert into public.knowledge_sources (source_key, title, source_url, authority, jurisdiction, domain, source_type, priority, tags, cache_days, is_active) values ('tw-tfda-illegal-advertising-query', 'Illegal Food, Drug, and Cosmetics Advertising Query System', 'http://pmds.fda.gov.tw/illegalad/', 'Taiwan Food and Drug Administration / PMDS', 'TW', 'food_labeling', 'database', 'high', '["food","drugs","cosmetics","advertising","violation","query","consumer"]'::jsonb, 7, true) on conflict (source_key) do update set title = excluded.title, source_url = excluded.source_url, authority = excluded.authority, jurisdiction = excluded.jurisdiction, domain = excluded.domain, source_type = excluded.source_type, priority = excluded.priority, tags = excluded.tags, cache_days = excluded.cache_days, is_active = true;
insert into public.knowledge_snapshots (source_key, content_hash, fetched_at, from_cache, bytes, text_chars, document_path, extract, metadata) values ('tw-tfda-illegal-advertising-query', '6937af3da999bb6833ed52af98451dd653a6ea32358c0c51ad170c364a770897', '2026-07-05T14:00:13.716Z', false, 2193, 2193, 'data/knowledge/documents/tw-tfda-illegal-advertising-query.md', 'Official TFDA / PMDS illegal food, drug, and cosmetics advertising query system for enforcement lookup. Use this as a companion source when screening Taiwan food or cosmetics label claims, health-food effects, medical-efficacy wording, false or exaggerated advertising, therapeutic implication, before-after claims, and missing substantiation. The system is operational rather than explanatory: reviewers should use it to compare risky wording against violation records and enforcement examples for food, drug, and cosmetics advertising. In LabelPass, route claim-heavy products here when the label or marketing draft mentions disease treatment, body-function improvement, slimming, whitening, anti-inflammatory, antibacterial, detox, immune, medical efficacy, or approved health-care effects. The review workflow should record the search keyword, product category, brand or product name, wording under review, and whether a similar violation appears in the query result. For Taiwan food, pair this lookup with false, exaggerated, misleading, or medical-efficacy claim rules, nutrition-claim guidance, sweetness-claim guidance, health-food permit checks, and special disease formula permit checks. For Taiwan cosmetics, pair it with cosmetic labeling and claims criteria, product notification, PIF substantiation, restricted ingredient evidence, and adverse-event or recall routing when safety claims are involved. The source should trigger a conservative result when marketing copy implies treatment, prevention, diagnosis, cure, body-structure change, disease-specific benefit, guaranteed effect, or government approval beyond the actual permit scope. It should also be used during Korean-to-Traditional-Chinese claim translation review, because the same Korean ingredient or efficacy wording may map to multiple Taiwan enforcement terms. Store search keywords and screenshots in the review file when a close precedent is found, then link the result back to the product claim, evidence document, and final label decision. If the portal is not reachable by automated collection, keep this manual record as the stable knowledge anchor and refresh by browser capture when the site is available.', '{"source_registry_version":"2026-06-26","source_ops_metadata_version":"2026-06-26","authority":"Taiwan Food and Drug Administration / PMDS","domain":"food_labeling","tags":["food","drugs","cosmetics","advertising","violation","query","consumer"],"source_ops":{"id":"tw-tfda-illegal-advertising-query","languages":["zh-Hant"],"review_owner":"tw-food-labeling","selector_strategy":"browser-visible-text-capture","date_strategy":"page-update-or-publication-date","refresh_strategy":"weekly-high-priority-watch","evidence_policy":"browser-text-and-screenshot"},"languages":["zh-Hant"],"review_owner":"tw-food-labeling","selector_strategy":"browser-visible-text-capture","date_strategy":"page-update-or-publication-date","refresh_strategy":"weekly-high-priority-watch","evidence_policy":"browser-text-and-screenshot","format":"manual","page_count":null,"parse_error":null,"fetched_url":"http://pmds.fda.gov.tw/illegalad/","extra_fetched_urls":[],"cache_days":7,"cache_expires_at":"2026-07-12T14:00:13.716Z","cache_status":"fresh","browser_capture_path":"data/knowledge/browser-captures/tw-tfda-illegal-advertising-query.txt","screenshot_path":"data/knowledge/browser-captures/tw-tfda-illegal-advertising-query.png"}'::jsonb) on conflict (source_key, content_hash) do update set fetched_at = excluded.fetched_at, from_cache = excluded.from_cache, bytes = excluded.bytes, text_chars = excluded.text_chars, document_path = excluded.document_path, extract = excluded.extract, metadata = excluded.metadata;
