ion Statistics Annual Reports Related Websites ::: Copyright Privacy Policy Plans and Policies Disclaimer Accessibility & Brower Suggestion Address：100025 No.4, Sec.1, Jinan Rd., Taipei City 100, Taiwan(R.O.C.) Service Hours: 8:30 to 17:30, Monday to Friday Tel：+886-2-23431700 Best viewed with IE11 & FireFox & Chrome Updated: 2026年6月25日 top', '{"source_registry_version":"2026-06-26","source_ops_metadata_version":"2026-06-26","authority":"Ministry of Economic Affairs / Bureau of Standards, Metrology and Inspection","domain":"product_certification","tags":["bsmi","commodity-inspection-mark","product-safety"],"source_ops":{"id":"tw-bsmi-commodity-inspection-mark","languages":["zh-Hant"],"review_owner":"product-certification","selector_strategy":"official-index-listing-extract","date_strategy":"index-item-publication-date-scan","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"official-page-text-cache"},"languages":["zh-Hant"],"review_owner":"product-certification","selector_strategy":"official-index-listing-extract","date_strategy":"index-item-publication-date-scan","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"official-page-text-cache","format":"html","page_count":null,"parse_error":null,"fetched_url":"https://www.bsmi.gov.tw/wSite/ct?ctNode=3563&mp=2&xItem=20603","extra_fetched_urls":[],"cache_days":30,"cache_expires_at":"2026-07-25T13:02:22.641Z","cache_status":"fresh","browser_capture_path":null,"screenshot_path":null}'::jsonb) on conflict (source_key, content_hash) do update set fetched_at = excluded.fetched_at, from_cache = excluded.from_cache, bytes = excluded.bytes, text_chars = excluded.text_chars, document_path = excluded.document_path, extract = excluded.extract, metadata = excluded.metadata;
