insert into public.knowledge_snapshots (source_key, content_hash, fetched_at, from_cache, bytes, text_chars, document_path, extract, metadata) values ('asean-rules-of-origin-registry', '704ab5e9a8ff64151e8079f4196bed303e8880be902e4e1a40e7b98258030389', '2026-06-25T13:03:17.756Z', true, 12448, 888, 'data/knowledge/documents/asean-rules-of-origin-registry.md', 'Rules of origin - ASEAN Trade Repository ASEAN Trade Repository Home About ATR NTRs Enquiries Topics Standards Contact Disclaimer 3 Rules of origin Rules of origin are laws, regulations and administrative determinations of general application applied to determine the country of origin of goods. They provide the &lsquo; economic nationality &rsquo; of goods in international trade. There are two kinds of rules of origin: non-preferential and preferential rules of origin. Sub Topic 3.1 Non-preferential rules of origin 3.2 Preferential rules of origin Brunei Darussalam Cambodia Indonesia Lao PDR Malaysia Myanmar Philippines Singapore Thailand Vietnam Follow us on Twitter Facebook Google YouTube --> ASEAN Trade Repository - Supported by ARISE + The ASEAN Secretariat - 70A Jl. Sisingamangaraja - Jakarta 12110 - Indonesia Tel : (6221) 7262991, 7243372 / Fax : (6221) 7398234, 7243504', '{"source_registry_version":"2026-06-26","source_ops_metadata_version":"2026-06-26","authority":"ASEAN Trade Repository","domain":"origin_labeling","tags":["asean","rules-of-origin","fta","trade"],"source_ops":{"id":"asean-rules-of-origin-registry","languages":["en"],"review_owner":"origin-labeling","selector_strategy":"official-html-main-content","date_strategy":"page-update-or-publication-date","refresh_strategy":"monthly-watch","evidence_policy":"official-page-text-cache"},"languages":["en"],"review_owner":"origin-labeling","selector_strategy":"official-html-main-content","date_strategy":"page-update-or-publication-date","refresh_strategy":"monthly-watch","evidence_policy":"official-page-text-cache","format":"html","page_count":null,"