insert into public.knowledge_sources (source_key, title, source_url, authority, jurisdiction, domain, source_type, priority, tags, cache_days, is_active) values ('tw-tfda-cosmetic-label-leaflet-packaging-marking', 'Cosmetic Outer Package, Container, Label and Package Insert Marking Rules', 'https://www.fda.gov.tw/tc/includes/GetFile.ashx?id=f636948036356063048', 'Taiwan Food and Drug Administration', 'TW', 'cosmetics', 'regulation', 'high', '["cosmetics","labeling","outer-package","container","package-insert","mandatory-label-items","inci","color-index","fragrance","may-contain"]'::jsonb, 30, true) on conflict (source_key) do update set title = excluded.title, source_url = excluded.source_url, authority = excluded.authority, jurisdiction = excluded.jurisdiction, domain = excluded.domain, source_type = excluded.source_type, priority = excluded.priority, tags = excluded.tags, cache_days = excluded.cache_days, is_active = true;
insert into public.knowledge_snapshots (source_key, content_hash, fetched_at, from_cache, bytes, text_chars, document_path, extract, metadata) values ('tw-tfda-cosmetic-label-leaflet-packaging-marking', 'e0b22caaa6dd3ece7ff377fb3c81692872cbcc17cdc42960f97e775d6a985f68', '2026-06-26T12:20:54.894Z', true, 181309, 1192, 'data/knowledge/documents/tw-tfda-cosmetic-label-leaflet-packaging-marking.md', '化粧品外包裝、容器、標籤或仿單之標示規定 一、本規定依化粧品衛生安全管理法（以下簡稱本法）第七條第四項 規定訂定之。 二、化粧品之外包裝或容器，應依本法第七條第一項所定應標示事項 明顯標示。但具外包裝及容器者，除於外包裝明顯處標示中文品 名外，容器應至少標示中文或外文品名。 三、本法第七條第一項應標示之事項，其字體大小規格如下： (一) 產品內容物淨重或容量大於 800 g 或 800 mL 者，其高度及 寬度均不得小於 2.0 mm。 (二) 產品內容物淨重或容量小於（含）800 g 或 800 mL 大於 300 g 或 300 mL 者，其高度及寬度均不得小於 1.6 mm。 (三) 產品內容物淨重或容量小於（含）300 g 或 300 mL 者，其 高度及寬度均不得小於 1.2 mm。 四、化粧品外包裝或容器最大之表面積小於四十平方公分者，其依本 法第七條第一項規定應標示之事項，應標示於標籤、仿單、卡片、 吊牌或說明書。 前項產品之外包裝、標籤或容器上應至少標示下列各款事項： (一) 品名。 (二) 用途。 (三) 製造或輸入業者之名稱。 (四) 製造日期及有效期間，或製造日期及保存期限，或有效期間 及保存期限。 五、全成分名稱，應參照 International Nomenclature of Cosmetic Ingredients (INCI)、中華藥典、美國藥典(United States Pharmacopoeia)或歐洲藥典(European Pharmacopoeia)，或其 他公定書或藥典，以中文或英文標示。 六、色素成分之標示得參照美國食品藥物管理局之 Color Index (CI) -- 1 of 2 -- 或 EC Directive Annex IV 命名法。 七、香精及香料之標示，得以香精、香料、Flavor、 Fragrance、Parfum、 Perfume 或 Aroma 表示之。 八、成分名稱應依其含量（淨重或容量），由高至低排列標示。但成 分屬下列各款之一者，得於產品中其他含量大於百分之一之成分 後任意排列： (一) 成分含量小於或等於百分之一。 (二) 彩粧類產品使用之色素成分。 九、彩粧系列產品應標示其加入色素之名稱；其可能加入之色素得載 明下列字樣之一而為標示： (一) +\–。 (二) may contain。 (三) 可能加入之色素。 十、本法第七條第一項第八款之標示事項，應以壓印或不褪色油墨印 刷、打印等方式，標示於外包裝、容器或標籤之上。 前項標示之期日應依習慣能辨明之方式標明年月日，製造日期 或保存期限得僅標明年月，並以當月之末日為製造日或期限終止 日。 十一、 前點第一項以標籤為之者，其所有標示項目應以不褪色油墨， 印刷或打印於同一張標籤，不得分別為之。 -- 2 of 2 --', '{"source_registry_version":"2026-06-26","source_ops_metadata_version":"2026-06-26","authority":"Taiwan Food and Drug Administration","domain":"cosmetics","tags":["cosmetics","labeling","outer-package","container","package-insert","mandatory-label-items","inci","color-index","fragrance","may-contain"],"source_ops":{"id":"tw-tfda-cosmetic-label-leaflet-packaging-marking","languages":["zh-Hant"],"review_owner":"tw-cosmetics-labeling-pif","selector_strategy":"pdf-text-extract","date_strategy":"pdf-frontmatter-or-notice-date","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"pdf-text-cache"},"languages":["zh-Hant"],"review_owner":"tw-cosmetics-labeling-pif","selector_strategy":"pdf-text-extract","date_strategy":"pdf-frontmatter-or-notice-date","refresh_strategy":"monthly-high-priority-watch","evidence_policy":"pdf-text-cache","format":"pdf","page_count":2,"parse_error":null,"fetched_url":"https://www.fda.gov.tw/tc/includes/GetFile.ashx?id=f636948036356063048","extra_fetched_urls":[],"cache_days":30,"cache_expires_at":"2026-07-26T12:20:54.894Z","cache_status":"fresh","browser_capture_path":null,"screenshot_path":null}'::jsonb) on conflict (source_key, content_hash) do update set fetched_at = excluded.fetched_at, from_cache = excluded.from_cache, bytes = excluded.bytes, text_chars = excluded.text_chars, document_path = excluded.document_path, extract = excluded.extract, metadata = excluded.metadata;
